"use client"

import { Meter as MeterPrimitive } from "@base-ui/react/meter"
import { cva, type VariantProps } from "class-variance-authority"
import { cn } from "cn"

// NOTE: Update these paths if needed
import "../tokens.css"
import "./meter.css"

function withBase<State>(
  base: string,
  className?: string | ((state: State) => string | undefined)
) {
  return (state: State) =>
    cn(base, typeof className === "function" ? className(state) : className)
}

const meterVariants = cva("np-meter", {
  variants: {
    variant: {
      default: "",
      success: "np-meter-success",
      warning: "np-meter-warning",
      destructive: "np-meter-destructive",
    },
    size: {
      default: "",
      sm: "np-meter-sm",
      lg: "np-meter-lg",
    },
  },
  defaultVariants: { variant: "default", size: "default" },
})

type MeterProps = MeterPrimitive.Root.Props & {
  variant?: NonNullable<VariantProps<typeof meterVariants>["variant"]>
  size?: NonNullable<VariantProps<typeof meterVariants>["size"]>
}

function Meter({
  className,
  variant = "default",
  size = "default",
  children,
  ...props
}: MeterProps) {
  return (
    <MeterPrimitive.Root
      data-slot="meter"
      data-variant={variant}
      data-size={size}
      className={withBase(meterVariants({ variant, size }), className)}
      {...props}
    >
      {children ?? (
        <MeterTrack>
          <MeterIndicator />
        </MeterTrack>
      )}
    </MeterPrimitive.Root>
  )
}

function MeterTrack({ className, ...props }: MeterPrimitive.Track.Props) {
  return (
    <MeterPrimitive.Track
      data-slot="meter-track"
      className={withBase("np-meter-track", className)}
      {...props}
    />
  )
}

function MeterIndicator({
  className,
  ...props
}: MeterPrimitive.Indicator.Props) {
  return (
    <MeterPrimitive.Indicator
      data-slot="meter-indicator"
      className={withBase("np-meter-indicator", className)}
      {...props}
    />
  )
}

function MeterLabel({ className, ...props }: MeterPrimitive.Label.Props) {
  return (
    <MeterPrimitive.Label
      data-slot="meter-label"
      className={withBase("np-meter-label", className)}
      {...props}
    />
  )
}

function MeterValue({ className, ...props }: MeterPrimitive.Value.Props) {
  return (
    <MeterPrimitive.Value
      data-slot="meter-value"
      className={withBase("np-meter-value", className)}
      {...props}
    />
  )
}

export {
  Meter,
  MeterIndicator,
  MeterLabel,
  MeterTrack,
  MeterValue,
  meterVariants,
}

export type { MeterProps }

/* nepui - Meter */

.np-meter,
[data-np-meter] {
  --np-meter-height: calc(var(--np-spacing, 0.25rem) * 2);
  --np-meter-color: var(--np-primary);
  --np-meter-track: color-mix(in oklch, var(--np-meter-color), transparent 80%);
  --np-meter-duration: 500ms;

  box-sizing: border-box;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  width: 100%;
}

.np-meter-label,
[data-np-meter-label] {
  grid-column: 1;
  grid-row: 1;
  padding-block-end: calc(var(--np-spacing, 0.25rem) * 2);
  color: var(--np-foreground);
  font-size: 0.875rem;
  font-weight: 500;
  line-height: 1.25;
}

.np-meter-value,
[data-np-meter-value] {
  grid-column: 2;
  grid-row: 1;
  justify-self: end;
  padding-block-end: calc(var(--np-spacing, 0.25rem) * 2);
  padding-inline-start: calc(var(--np-spacing, 0.25rem) * 2);
  color: var(--np-muted-foreground);
  font-size: 0.875rem;
  font-variant-numeric: tabular-nums;
  line-height: 1.25;
}

.np-meter-track,
[data-np-meter-track] {
  grid-column: 1 / -1;
  grid-row: 2;
  box-sizing: border-box;
  position: relative;
  display: block;
  width: 100%;
  height: var(--np-meter-height);
  overflow: hidden;
  background-color: var(--np-meter-track);
}

.np-meter-indicator,
[data-np-meter-indicator] {
  display: block;
  width: var(--np-meter-percentage, 0%);
  height: 100%;
  border-radius: inherit;
  background-color: var(--np-meter-color);
  transition: width var(--np-meter-duration) ease;
}

meter:is(.np-meter-track, [data-np-meter-track]) {
  -webkit-appearance: none;
  appearance: none;
  border: 0;
}

meter:is(.np-meter-track, [data-np-meter-track])::-webkit-meter-inner-element {
  box-sizing: border-box;
  height: var(--np-meter-height);
}

meter:is(.np-meter-track, [data-np-meter-track])::-webkit-meter-bar {
  box-sizing: border-box;
  height: var(--np-meter-height);
  border: 0;
  background: none;
}

meter:is(.np-meter-track, [data-np-meter-track])::-webkit-meter-optimum-value,
meter:is(
    .np-meter-track,
    [data-np-meter-track]
  )::-webkit-meter-suboptimum-value,
meter:is(
    .np-meter-track,
    [data-np-meter-track]
  )::-webkit-meter-even-less-good-value {
  box-sizing: border-box;
  height: var(--np-meter-height);
  background: var(--np-meter-color);
  transition: width var(--np-meter-duration) ease;
}

meter:is(.np-meter-track, [data-np-meter-track])::-moz-meter-bar {
  box-sizing: border-box;
  height: var(--np-meter-height);
  background: var(--np-meter-color);
}

:is(.np-meter, [data-np-meter]):is(
  .np-meter-success,
  [data-variant="success"]
) {
  --np-meter-color: var(--np-success);
}

:is(.np-meter, [data-np-meter]):is(
  .np-meter-warning,
  [data-variant="warning"]
) {
  --np-meter-color: var(--np-warning);
}

:is(.np-meter, [data-np-meter]):is(
  .np-meter-destructive,
  [data-variant="destructive"]
) {
  --np-meter-color: var(--np-destructive);
}

:is(.np-meter, [data-np-meter]):is(.np-meter-sm, [data-size="sm"]) {
  --np-meter-height: calc(var(--np-spacing, 0.25rem) * 1);
}

:is(.np-meter, [data-np-meter]):is(.np-meter-lg, [data-size="lg"]) {
  --np-meter-height: calc(var(--np-spacing, 0.25rem) * 3);
}

@media (prefers-reduced-motion: reduce) {
  .np-meter-indicator,
  [data-np-meter-indicator],
  meter:is(.np-meter-track, [data-np-meter-track])::-webkit-meter-optimum-value,
  meter:is(
      .np-meter-track,
      [data-np-meter-track]
    )::-webkit-meter-suboptimum-value,
  meter:is(
      .np-meter-track,
      [data-np-meter-track]
    )::-webkit-meter-even-less-good-value {
    transition: none;
  }
}
